package trackconfig

import (
	"fmt"
	"go/format"
	"strings"

	"github.com/shopspring/decimal"
)

const generatedHeader = "Code generated by `simgen generate-track-constants` from " +
	"platform/shared/config/track.toml. DO NOT EDIT."

// f renders a decimal as a float literal, exactly, always keeping a decimal
// point (e.g. 0.30 -> "0.3", 3 -> "3.0").
//
// The value is emitted straight from the decimal rather than round-tripped
// through float64, so the literal in the generated file is the decimal the mat
// has. The decimal point is not cosmetic on the Python side: `TRACK_SIZE:
// Final[float] = 3` binds an int at runtime, which would give a whole-number
// length a different type from its neighbours.
func f(d decimal.Decimal) string {
	s := d.String()
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}

// goFloats renders a slice as a Go array literal with an inferred length.
func goFloats(vs []decimal.Decimal) string {
	parts := make([]string, len(vs))
	for i, v := range vs {
		parts[i] = f(v)
	}
	return "[...]float64{" + strings.Join(parts, ", ") + "}"
}

// goRGB renders a colour as a Go array literal.
func goRGB(c RGB) string {
	return fmt.Sprintf("[3]float64{%s, %s, %s}", f(c[0]), f(c[1]), f(c[2]))
}

// GenerateGo renders cfg as a Go const/var block for package simconfig.
func GenerateGo(cfg *Config, robotWidth decimal.Decimal) (string, error) {
	var sb strings.Builder
	bands := cfg.Corridor.BandWidths()
	lines := cfg.Corridor.DivisionLines
	left, right := cfg.CellCentersAlong()
	offsets, err := cfg.SpawnOffsets(robotWidth)
	if err != nil {
		return "", err
	}

	fmt.Fprintf(&sb, "// %s\n\n", generatedHeader)
	sb.WriteString("package simconfig\n\n")

	sb.WriteString("// Track dimensions (meters). Official WRO 2026 Future Engineers spec.\n")
	sb.WriteString("const (\n")
	fmt.Fprintf(&sb, "\tTrackMatSize     = %s\n", f(cfg.Track.MatSize))
	fmt.Fprintf(&sb, "\tTrackSize        = %s\n", f(cfg.Track.Size))
	fmt.Fprintf(&sb, "\tTrackMinCoord    = %s\n", f(cfg.Track.MinCoord))
	fmt.Fprintf(&sb, "\tTrackMaxCoord    = %s\n", f(cfg.Track.MaxCoord))
	fmt.Fprintf(&sb, "\tTrackCenterCoord = %s\n", f(cfg.Track.CenterCoord()))
	fmt.Fprintf(&sb, "\tTrackCornerMin   = %s\n", f(cfg.Track.CornerMin))
	fmt.Fprintf(&sb, "\tTrackCornerMax   = %s\n", f(cfg.Track.CornerMax))
	fmt.Fprintf(&sb, "\tTrackCornerSize  = %s\n", f(cfg.Track.CornerSize()))
	sb.WriteString(")\n\n")

	sb.WriteString("// Wall dimensions (meters).\n")
	sb.WriteString("const (\n")
	fmt.Fprintf(&sb, "\tWallHeight             = %s\n", f(cfg.Wall.Height))
	fmt.Fprintf(&sb, "\tWallThickness          = %s\n", f(cfg.Wall.Thickness))
	fmt.Fprintf(&sb, "\tWallCollisionThickness = %s\n", f(cfg.Wall.CollisionThickness))
	fmt.Fprintf(&sb, "\tWallExteriorOffset     = %s\n", f(cfg.Wall.ExteriorOffset))
	fmt.Fprintf(&sb, "\tWallInteriorOffset     = %s\n", f(cfg.Wall.InteriorOffset))
	sb.WriteString(")\n\n")

	sb.WriteString("// Corridor widths (meters).\n")
	sb.WriteString("const (\n")
	fmt.Fprintf(&sb, "\tCorridorNarrow    = %s\n", f(cfg.Corridor.Narrow))
	fmt.Fprintf(&sb, "\tCorridorWide      = %s\n", f(cfg.Corridor.Wide))
	fmt.Fprintf(&sb, "\tCorridorObstacles = %s\n", f(cfg.Corridor.Obstacles))
	fmt.Fprintf(&sb, "\tCorridorMinWidth  = %s\n", f(cfg.Corridor.MinWidth))
	fmt.Fprintf(&sb, "\tCorridorMaxWidth  = %s\n", f(cfg.Corridor.MaxWidth))
	sb.WriteString("\n\t// Division lines painted across every corridor, out from the outer wall.\n")
	fmt.Fprintf(&sb, "\tCorridorDivOuter = %s\n", f(lines[0]))
	fmt.Fprintf(&sb, "\tCorridorDivInner = %s\n", f(lines[len(lines)-1]))
	fmt.Fprintf(&sb, "\tCorridorDivWidth = %s\n", f(bands[1]))
	sb.WriteString(")\n\n")

	sb.WriteString("// Traffic sign dimensions and grid positions (meters). WRO Spec 13.21-13.22.\n")
	sb.WriteString("const (\n")
	fmt.Fprintf(&sb, "\tSignWidth           = %s\n", f(cfg.Sign.Width))
	fmt.Fprintf(&sb, "\tSignDepth           = %s\n", f(cfg.Sign.Depth))
	fmt.Fprintf(&sb, "\tSignHeight          = %s\n", f(cfg.Sign.Height))
	fmt.Fprintf(&sb, "\tSignZPosition       = %s\n", f(cfg.Sign.ZPosition))
	fmt.Fprintf(&sb, "\tSignGridDepthNear   = %s\n", f(cfg.Sign.GridDepthNear))
	fmt.Fprintf(&sb, "\tSignGridDepthMiddle = %s\n", f(cfg.Sign.GridDepthMid))
	fmt.Fprintf(&sb, "\tSignGridDepthFar    = %s\n", f(cfg.Sign.GridDepthFar))
	sb.WriteString("\t// Pillars stand on the corridor division lines.\n")
	fmt.Fprintf(&sb, "\tSignGridWidthOuter = %s\n", f(lines[0]))
	fmt.Fprintf(&sb, "\tSignGridWidthInner = %s\n", f(lines[len(lines)-1]))
	sb.WriteString("\t// Circle each pillar is placed within. Nudging a pillar is legal; the run\n")
	sb.WriteString("\t// stays valid while ANY corner of its square is still inside this circle.\n")
	fmt.Fprintf(&sb, "\tSignPlacementCircleDiameter = %s\n", f(cfg.Sign.PlacementCircleDiameter))
	fmt.Fprintf(&sb, "\tSignMinCount       = %d\n", cfg.Sign.MinCount)
	fmt.Fprintf(&sb, "\tSignMaxCount       = %d\n", cfg.Sign.MaxCount)
	sb.WriteString(")\n\n")

	sb.WriteString("// Parking block dimensions (meters, obstacles challenge only).\n")
	sb.WriteString("const (\n")
	fmt.Fprintf(&sb, "\tParkingLength        = %s\n", f(cfg.Parking.Length))
	fmt.Fprintf(&sb, "\tParkingWidth         = %s\n", f(cfg.Parking.Width))
	fmt.Fprintf(&sb, "\tParkingHeight        = %s\n", f(cfg.Parking.Height))
	fmt.Fprintf(&sb, "\tParkingZPosition     = %s\n", f(cfg.Parking.ZPosition))
	fmt.Fprintf(&sb, "\tParkingWallOffset    = %s\n", f(cfg.Parking.WallOffset))
	fmt.Fprintf(&sb, "\tParkingSpacingFactor = %s\n", f(cfg.Parking.SpacingFactor))
	sb.WriteString(")\n\n")

	sb.WriteString("// Starting zone dimensions (meters).\n")
	sb.WriteString("const (\n")
	fmt.Fprintf(&sb, "\tStartingZoneDefaultLength   = %s\n", f(cfg.StartingZone.DefaultLength))
	sb.WriteString("\t// StartingZoneWidth is the middle band's width, used for the parking-derived\n")
	sb.WriteString("\t// zone and the base template placeholder. Open Challenge zones are as wide as\n")
	sb.WriteString("\t// whichever band their cell sits in -- see StartingZoneBandWidths.\n")
	fmt.Fprintf(&sb, "\tStartingZoneWidth           = %s\n", f(bands[1]))
	fmt.Fprintf(&sb, "\tStartingZoneThickness       = %s\n", f(cfg.StartingZone.Thickness))
	fmt.Fprintf(&sb, "\tStartingZoneObstaclesFactor = %s\n", f(cfg.StartingZone.ObstaclesSizeFactor))
	fmt.Fprintf(&sb, "\tStartingZoneIndicatorRadius = %s\n", f(cfg.StartingZone.IndicatorRadius))
	sb.WriteString(")\n\n")

	sb.WriteString("// Along-corridor midpoints of the two starting cells in each band.\n")
	sb.WriteString("const (\n")
	fmt.Fprintf(&sb, "\tGridLengthSectionLeft  = %s\n", f(left))
	fmt.Fprintf(&sb, "\tGridLengthSectionRight = %s\n", f(right))
	sb.WriteString(")\n\n")

	sb.WriteString("var (\n")
	sb.WriteString("\t// WallColor is the normalized RGB for all walls.\n")
	fmt.Fprintf(&sb, "\tWallColor = %s\n\n", goRGB(cfg.Wall.Color))
	sb.WriteString("\t// SignColorRed is the official WRO red pillar color (RGB normalized).\n")
	fmt.Fprintf(&sb, "\tSignColorRed = %s\n\n", goRGB(cfg.Sign.RedColor))
	sb.WriteString("\t// SignColorGreen is the official WRO green pillar color (RGB normalized).\n")
	fmt.Fprintf(&sb, "\tSignColorGreen = %s\n\n", goRGB(cfg.Sign.GreenColor))
	sb.WriteString("\t// SignColorRedStd is the per-channel stddev for red pillar color noise.\n")
	fmt.Fprintf(&sb, "\tSignColorRedStd = %s\n\n", goRGB(cfg.Sign.RedColorStd))
	sb.WriteString("\t// SignColorGreenStd is the per-channel stddev for green pillar color noise.\n")
	fmt.Fprintf(&sb, "\tSignColorGreenStd = %s\n\n", goRGB(cfg.Sign.GreenColorStd))
	sb.WriteString("\t// ParkingColor is the magenta parking block color (RGB normalized).\n")
	fmt.Fprintf(&sb, "\tParkingColor = %s\n\n", goRGB(cfg.Parking.Color))
	sb.WriteString("\t// StartingZoneColor is the grey base rectangle color.\n")
	fmt.Fprintf(&sb, "\tStartingZoneColor = %s\n\n", goRGB(cfg.StartingZone.Color))
	sb.WriteString("\t// StartingZoneClockwiseColor marks a clockwise round.\n")
	fmt.Fprintf(&sb, "\tStartingZoneClockwiseColor = %s\n\n", goRGB(cfg.StartingZone.ClockwiseColor))
	sb.WriteString("\t// StartingZoneCounterClockwiseColor marks a counterclockwise round.\n")
	fmt.Fprintf(&sb, "\tStartingZoneCounterClockwiseColor = %s\n\n", goRGB(cfg.StartingZone.CounterClockwise))

	sb.WriteString("\t// StartingZoneBandWidths are the starting square's bands across the\n")
	sb.WriteString("\t// corridor, measured out from the outer wall. Derived from the corridor\n")
	sb.WriteString("\t// division lines: they are the widths those lines delimit.\n")
	sb.WriteString("\t//\n")
	sb.WriteString("\t// The band widths are what make the layout conditional. A band is a legal\n")
	sb.WriteString("\t// start only while it lies inside the corridor, so a narrow corridor holds\n")
	sb.WriteString("\t// only the outer bands and a wide one holds them all. See generate.StartCells.\n")
	fmt.Fprintf(&sb, "\tStartingZoneBandWidths = %s\n\n", goFloats(bands))
	sb.WriteString("\t// StartingZoneSpawnOffsets are where the robot is placed inside each band,\n")
	sb.WriteString("\t// out from the outer wall -- absolute metres, not fractions of the corridor.\n")
	sb.WriteString("\t//\n")
	sb.WriteString("\t// Derived by pushing the chassis flush against the band edge named in\n")
	sb.WriteString("\t// track.toml's spawn_alignment, never centred: one band edge is a painted\n")
	sb.WriteString("\t// line the robot can sit against harmlessly, the other may be the inner\n")
	sb.WriteString("\t// block, so splitting the slack evenly would spend half the margin on the\n")
	sb.WriteString("\t// line. Recomputed from the chassis width, so it follows a re-measurement.\n")
	fmt.Fprintf(&sb, "\tStartingZoneSpawnOffsets = %s\n", goFloats(offsets))
	sb.WriteString(")\n")

	formatted, err := format.Source([]byte(sb.String()))
	if err != nil {
		return "", fmt.Errorf("format generated go source: %w", err)
	}
	return string(formatted), nil
}

